// src/stores/notifications.js
import { defineStore } from 'pinia';
import { usersTable } from '@/idb/db';

export const useNotificationsStore = defineStore('notifications', {
    state: () => ({
        notifications: [],
        currentUserId: null,
        isInitialized: false,
        loading: false,
        autoCloseTimers: new Map()
    }),

    getters: {
        // Все уведомления
        all: (state) => state.notifications,
        // Все актуальные (учет по дате начала и дате закрытия) уведомления
        allActual: (state) => {
            const now = Date.now();
            return state.notifications.filter(n =>
                (!n.createdAt || n.createdAt <= now) &&
                (!n.endAt     || n.endAt     >  now)
            );
        },

        // Непрочитанные
        unread: (state) => state.notifications.filter(n => !n.read),
        // Непрочитанные актуальные
        unreadActual() { return this.allActual.filter(n => !n.read); },
    
        // Количество непрочитанных
        unreadCount() { return this.unread.length; },
        // Количество актуальных непрочитанных
        unreadActualCount() { return this.unreadActual.length; },

        // Закрепленные
        pinned: (state) => state.notifications.filter(n => n.pinned),
        // Закрепленные актуальные
        pinnedActual() { return this.allActual.filter(n => n.pinned); },

        // По приложению
        getForApp() { return (appId) => this.all.filter(n => n.app === appId); },
        // По приложению актуальные
        getForAppActual() { return (appId) => this.allActual.filter(n => n.app === appId); },

        // По типу
        getByType() { return (type) => this.all.filter(n => n.type === type); },
        // По типу актуальные
        getByTypeActual() { return (type) => this.allActual.filter(n => n.type === type); },

        // Последние N
        getRecent() { return (count = 5) => this.all.slice(0, count); },
        // Последние N актуальные
        getRecentActual() { return (count = 5) => this.allActual.slice(0, count); }
    },

    actions: {
        // Инициализация для пользователя
        async init(userId) {
            if (!userId) {
                console.warn('NotificationsStore: No userId provided');
                return;
            }

            this.currentUserId = userId;
            this.loading = true;
        
            try {
                const notifs = await usersTable.notifs.getAll(userId);

                this.notifications = notifs;
                this.isInitialized = true;
            } catch (error) {
                console.error('Failed to initialize notifications store:', error);
            } finally {
                this.loading = false;
            }
        },

        // Добавление уведомления
        async add(notificationData) {
            if (!this.currentUserId) throw new Error('No user selected');

            try {
                const notification = await usersTable.notifs.add(this.currentUserId, notificationData);

                // Добавляем в начало списка
                this.notifications = [notification, ...this.notifications];
        
                // Автозакрытие
                if (notification.autoclose && notification.autoclose > 0) this.setAutoClose(notification.id, notification.autoclose);

                return notification;
            } catch (error) {
                console.error('Failed to add notification:', error);
                throw error;
            }
        },

        // Отметить как прочитанное
        async markAsRead(notificationId) {
            if (!this.currentUserId) return;

            try {
                await usersTable.notifs.markAsRead(this.currentUserId, notificationId);
        
                const notif = this.notifications.find(n => n.id === notificationId);
                if (notif) notif.read = true;
            } catch (error) {
                console.error('Failed to mark as read:', error);
            }
        },

        // Отметить все как прочитанные
        async markAllAsRead() {
            console.log('this.currentUserId', this.currentUserId);
            if (!this.currentUserId) return;

            console.log('usersTable.notifs', usersTable.notifs);

            try {                
                await usersTable.notifs.markAsReadAll(this.currentUserId);
                this.notifications.forEach(n => n.read = true);

                console.log('markAllAsRead::', 'ok');

                return "ok";
            } catch (error) {
                console.error('Failed to mark all as read:', error);
                return "error";
            }
        },
        // Отметить все как не прочитанные
        async markAllAsUnread() {
            if (!this.currentUserId) return;

            try {                
                await usersTable.notifs.markAsUnreadAll(this.currentUserId);
                this.notifications.forEach(n => n.read = false);

                return "ok";
            } catch (error) {
                console.error('Failed to mark all as unread:', error);
                return "error";
            }
        },

        // Удалить уведомление
        async remove(notificationId) {
            if (!this.currentUserId) return;

            try {
                await usersTable.notifs.delete(this.currentUserId, notificationId);
        
                this.notifications = this.notifications.filter(n => n.id !== notificationId);
        
                // Очищаем таймер
                if (this.autoCloseTimers.has(notificationId)) {
                    clearTimeout(this.autoCloseTimers.get(notificationId));
                    this.autoCloseTimers.delete(notificationId);
                }
            } catch (error) {
                console.error('Failed to remove notification:', error);
            }
        },

        // Очистить все (кроме закрепленных)
        async clearAll() {
            if (!this.currentUserId) return;

            try {
                await usersTable.notifs.clearAll(this.currentUserId);
                this.notifications = this.notifications.filter(n => n.pinned);
            } catch (error) {
                console.error('Failed to clear all:', error);
            }
        },

        // Закрепить/открепить
        async togglePinned(notificationId) {
            if (!this.currentUserId) return;

            try {
                const newState = await usersTable.notifs.togglePinned(this.currentUserId, notificationId);
                const notif = this.notifications.find(n => n.id === notificationId);
                
                if (notif) notif.pinned = newState;
        
                return newState;
            } catch (error) {
                console.error('Failed to toggle pinned:', error);
                return false;
            }
        },

        // Закрепить/открепить ВСЕ уведомления
        async setPinnedAll(pinned) {
            if (!this.currentUserId) return;
            await usersTable.notifs.setPinnedAll(this.currentUserId, pinned);
            this.notifications.forEach(n => n.pinned = pinned);
        },

        // Закрепить/открепить ВЫБРАННЫЕ уведомления
        async setPinnedMany(ids, pinned) {
            if (!this.currentUserId) return;
            await usersTable.notifs.setPinnedMany(this.currentUserId, ids, pinned);

            const idSet = new Set(ids);
            this.notifications.forEach(n => {
                if (idSet.has(n.id)) n.pinned = pinned;
            });
        },

        async setReadMany(ids, read) {
            if (!this.currentUserId) return;
            await usersTable.notifs.setReadMany(this.currentUserId, ids, read);
            const idSet = new Set(ids);
            this.notifications.forEach(n => {
                if (idSet.has(n.id)) n.read = read;
            });
        },

        async removeMany(ids) {
            if (!this.currentUserId) return;
            await usersTable.notifs.deleteMany(this.currentUserId, ids);
            const idSet = new Set(ids);
            this.notifications = this.notifications.filter(n => !idSet.has(n.id));

            // Почистить таймеры автозакрытия
            for (const id of ids) {
                if (this.autoCloseTimers.has(id)) {
                    clearTimeout(this.autoCloseTimers.get(id));
                    this.autoCloseTimers.delete(id);
                }
            }
        },

        // Автозакрытие
        setAutoClose(notificationId, seconds) {
            if (this.autoCloseTimers.has(notificationId)) clearTimeout(this.autoCloseTimers.get(notificationId));

            const timer = setTimeout(() => {
                this.remove(notificationId);
            }, seconds * 1000);

            this.autoCloseTimers.set(notificationId, timer);
        },

        // Очистка старых
        async cleanupOld(daysOld = 30) {
            if (!this.currentUserId) return 0;

            try {
                const cutoff = new Date();
                cutoff.setDate(cutoff.getDate() - daysOld);
        
                const toRemove = this.notifications.filter(n => {
                    if (n.pinned) return false;
                
                    const createdAt = new Date(n.createdAt);
                    return createdAt < cutoff;
                });

                for (const notif of toRemove) {
                    await this.remove(notif.id);
                }

                return toRemove.length;
            } catch (error) {
                console.error('Failed to cleanup old notifications:', error);
                return 0;
            }
        },

        // Сброс при выходе
        reset() {
            this.notifications = [];
            this.currentUserId = null;
            this.isInitialized = false;
            this.loading = false;
      
            for (const [, timer] of this.autoCloseTimers) {
                clearTimeout(timer);
            }
            this.autoCloseTimers.clear();
        }
    }
});